import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"13、【同人】 离下乾上","description":"周易阐真 - 13、【同人】 离下乾上","frontmatter":{"title":"13、【同人】 离下乾上","description":"周易阐真 - 13、【同人】 离下乾上"},"headers":[],"relativePath":"zh/classics/chanzhen/014.md","filePath":"zh/classics/chanzhen/014.md"}'),s={name:"zh/classics/chanzhen/014.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：同人，柔得位得中而应乎刚，曰同人。同人曰：“同人于野，亨。利涉大川。”乾行也。文明以健，中正而应，君子正也。唯君子为能通天下之志。</p></blockquote><h1 id="_13、【同人】-离下乾上" tabindex="-1">13、【同人】 离下乾上 <a class="header-anchor" href="#_13、【同人】-离下乾上" aria-label="Permalink to “13、【同人】 离下乾上”">​</a></h1><p>初九：同人于门，无咎。</p><p>六二：同人于宗，吝。</p><p>九三：伏戎于莽，升其高陵，三岁不兴。</p><p>九四：乘其墉，弗克攻，吉。</p><p>九五：同人，先号咷，而后笑。大师克相遇。</p><p>上九：同人于郊，无悔。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：天与火，同人。君子以类族辨物。</p><p>同人者，与人相同也。上乾天，下离日，日即火也。天无物不覆，日无物不照，天与日同处，公而且明，同人之象也。</p><p>君子有见于此，知修道者应世接物，贵乎能同于人，尤贵乎不苟同于人，以是类族辨物焉。类者，同一其类；族者，各一其族。如人高低贵贱，皆有其族。君子于各族，皆一类视之，无一不同。辨者，分别也；物者，邪正善恶之物。君子于物，而必辨之，无敢苟同。类族，所以法天之无私；辨物，所以效日之明照。既无私，又明照，天下无不可同之人，天下亦无苟同之物。盖君子同以道，而不同以心；同以理，而不同以人。所谓和而不流，群而不党，天日之同物如是，君子之同人亦如是也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>莽，莫荡反。墉，音庸。号，户羔反。咷，道力反。</p><p>同人者，人我如一之义。卦德上乾健，下离明，明而行健，健以通明，诚中达外，成己成物，故谓同人。此混俗和光，善与人同之卦，承上泰卦而来。泰者，阴阳相当，健顺如一也。</p><p>修道者，至阴阳相当，健顺如一，圣胎已结，可以混俗和光，以修向上事矣。但混俗和光，须要大公无私，在于无我。无我则无人，无我无人，则人我之心去。人我之心去，则人即是我，我即是人，如天之无物不覆，如日之无处不照，可以物我归空，如同人于野，同而未有不亨者也。野为旷远无人之处，同人如在野，则无我相，无人相，无众生相，是能实心同人矣。但能同之于顺，不能同之于逆，能同之于平易，不能同之于危险，则同之不是实心，而终不得亨。曰“利涉大川”者，以其大险大难之境。若能同去，则其无险无难之处，无往不利矣。</p><p>世之凡夫俗子，未尝无有同人者，但多出于私而不得其正，可同者同之，不可同者亦同之，非同人于野之旨，故涉川之利，其必利于君子之贞乎。君子者，同之以正，而不同之以心。正者，同理而已。心有变迁，理无变迁，以理而同，则无心，无心则人我之见俱化。惟理是守，内可以成己，外可以成物，明以照远，健以直行，健明两用，刚柔相济，内不失己，外不伤人，圆陀陀，光灼灼，净倮倮，赤洒洒，立于万物之中，而不为万物所屈，处于阴阳之内，而不为阳阴所拘矣。</p><p>初九，在同人之始，刚而能明，将欲出门同人，不遽出门，先辨其是非可否，而后同。同之能以无咎者。此刚而谨始之同也。</p><p>六二，居于内体，与二阳同处，是同人于宗，仅能同之于亲，不能同之于疏，乃同人羞吝之道。此柔而不远之同也。</p><p>九三，刚明太过，自尊自大，间或同人出于勉强，不由自然，如伏戎于莽，升其高陵也。高陵之同，顺我者能同，逆我者不能同。如此之人，虽三岁之久，终不能兴同人之事。此刚而勉强之同也。</p><p>九四，以刚乘刚，彼强我胜，彼我不能同心，如乘其墉而弗克攻矣。然刚而能柔，不能同而不强攻，亦同人之吉道。此刚而能柔之同也。</p><p>九五，刚健中正，道全德备，先无人同，而终必有同者，是同人先号咷而后笑也。夫道高者毁来，德修者谤兴，知音之少，亦无足怪。然成己之后，而欲成物，大公无私，以正而同，如大师克之，久则诚能动物，方且人人尊服，而皆同之，何患知音之不遇哉!此大公无私，利涉大川之同也。</p><p>上九，刚以柔用，在尘而能出尘，处世而能出世，外虽同而内不同，如同人于郊。于郊之同，大智若愚，大巧若拙，境遇不得而移，不致悔而自无悔。此和而不流之同也。</p><p>然则同人之道，须要通权达变，量时度务。同之得正为贵，以正而同，既健且明，无往而不可同，无往而有苟同，同人于野之旨得矣。</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
